const groupKeyOf = (v) => {
	const s = String(v ?? '').trim().replace(/^wechat(?::|-)?group:/i, '').replace(/^wechat:/i, '').replace(/^group:/i, '').replace(/@(im\.)?chatroom$/i, '').trim();
	return /^\d{1,12}$/.test(s) ? s : '';
};
// [FS-WECHAT-GROUPSET-LIST] 群设置页原来只列 QQ 群：微信群的群名、要不要接话、群设定都没地方管。
//   这里把微信接话名单里的群 + 有会话的微信群 + 已经写过群设定的微信群一起并进来，每条带 platform 给前端分栏。
//   微信群的群设定键用 wechat:<群号>@chatroom，跟 QQ 的纯数字群号分开，免得撞键串群。
const groups = () => {
	const notes = groupNotes(db);
	const out = [];
	const push = (groupId, channelId, fallback) => {
		if (!groupId || out.some((x) => x.groupId === groupId)) return;
		const heat = gateway?.heatOf?.(channelId) ?? null;
		const title = gateway?.titleOf?.(channelId, fallback) ?? fallback;
		out.push({ groupId, channelId, platform: String(channelId).startsWith('wechat:') ? 'wechat' : 'qq', title: String(title).replace(/^微信群·/, ''), note: notes[groupId]?.text ?? '', noteAt: notes[groupId]?.updatedAt ?? null, heat });
	};
	const qqNotes = Object.keys(notes).filter((k) => !String(k).startsWith('wechat:'));
	const qqIds = new Set([...chats().filter((c) => c.channelId.startsWith('group:')).map((c) => c.channelId.slice(6)), ...(getConfig().qq?.groupAllowList ?? []).map(String), ...qqNotes]);
	for (const id of [...qqIds].filter(Boolean)) push(String(id), `group:${id}`, `群 ${id}`);
	const wcfg = getConfig().wechat ?? {};
	const wl = (wcfg.groupAllowList ?? []).map(String);
	const wxRows = listChatSessions(db, 'wechat').filter((r) => String(r.channel_id).startsWith('wechat:group:'));
	const wxMap = new Map();
	for (const r of wxRows) { const n = groupKeyOf(r.channel_id); if (n !== '' && !wxMap.has(n)) wxMap.set(n, r); }
	const wxNotes = Object.keys(notes).filter((k) => String(k).startsWith('wechat:')).map(groupKeyOf);
	const allowed = new Set(wl.map(groupKeyOf).filter(Boolean));
	const wIds = [...new Set([...wl, ...wxMap.keys(), ...wxNotes].map(groupKeyOf).filter(Boolean))];
	for (const n of wIds) {
		const row = wxMap.get(n);
		push(`wechat:${n}@chatroom`, row ? String(row.channel_id) : `wechat:group:${n}@chatroom`, `微信群 ${n}`);
	}
	return out.map((g) => ({ ...g, allowed: g.platform === 'wechat' ? allowed.has(groupKeyOf(g.groupId)) : true, allowList: g.platform === 'wechat' ? [...allowed] : null }));
};

