/** 每个群：群设定（失焦保存）+ 现在冷不冷 + 微信群的接话开关 */
function GroupNote({ g, api, notify, onSaved, ui }) {
	const { h, Area, Tag, Muted } = ui;
	const [text, setText] = react.useState(g.note);
	react.useEffect(() => { setText(g.note); }, [g.note]);
	async function save() {
		if (text.trim() === g.note) return;
		const r = await api("POST", "/groups/note", { groupId: g.groupId, note: text });
		if (r?.ok) { notify(r.note ? "群设定已保存" : "群设定已清空"); onSaved(); } else notify(r?.error ?? "保存失败");
	}
	// [FS-WECHAT-GROUPSET-UI] 微信群要不要接话：勾上就把纯数字群号写进 wechat.groupAllowList（跟微信页那个开关同一份配置）
	const bare = (v) => String(v ?? "").replace(/^wechat(?::|-)?group:/i, "").replace(/^wechat:/i, "").replace(/^group:/i, "").replace(/@(im\.)?chatroom$/i, "").trim();
	const [on, setOn] = react.useState(g.allowed !== false);
	react.useEffect(() => { setOn(g.allowed !== false); }, [g.allowed]);
	const [busy, setBusy] = react.useState(false);
	async function pick(next) {
		if (busy) return;
		setBusy(true);
		setOn(next);
		const id = bare(g.groupId);
		const list = (Array.isArray(g.allowList) ? g.allowList : []).map(bare).filter((x) => x !== "" && x !== id);
		if (next) list.push(id);
		const r = await api("POST", "/channels/wechat-config", { groupAllowList: list });
		setBusy(false);
		if (r?.ok) { notify(next ? "这个群开始接话" : "这个群不再接话"); onSaved(); } else { setOn(!next); notify(r?.error ?? "保存失败"); }
	}
	const [label, tone] = HEAT[g.heat?.state] ?? HEAT.off;
	return h("div", { className: "fs-row stack", key: g.groupId },
		h("div", { className: "fs-row-title" }, h("div", { className: "fs-group-note-title" }, h("span", null, g.title),
			h("span", { className: "fs-unit" }, g.platform === "wechat" ? Muted("微信 ") : null, Tag(label, tone), g.heat && g.heat.count > 0 ? Muted(` 最近 ${g.heat.count} 条 · ${g.heat.speakers} 人`) : null))),
		g.platform === "wechat" ? h("label", { style: { display: "flex", alignItems: "center", gap: "6px", fontSize: "12px" } },
			h("input", { type: "checkbox", checked: on, disabled: busy, onChange: (e) => void pick(e.target.checked) }),
			Muted("这个群里接话（不勾就只在这个群当哑巴）")) : null,
		h("div", { className: "fs-ctl" }, Area({ value: text, rows: 2, maxLength: 500, "aria-label": `${g.title} 的群设定`,
			placeholder: "你在这个群是什么身份、气氛和忌讳（只在这个群里给她看），比如：考研群，你是过来人学姐，大家叫你鱼老师；别聊游戏",
			onChange: (e) => setText(e.target.value), onBlur: save })));
}
